package com.rostamvpn.android

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * A verified web App Link (`https://<host>/…`, hosts from the brand manifest's
 * `deepLinkHosts` via BuildConfig.DEEP_LINK_HOSTS) turned into a place in the app.
 *
 * The filter that delivers these is GENERATED by app/build.gradle.kts from the
 * same manifest field, with the same path list as [webLinkFor]; keep the two
 * together. A brand without `deepLinkHosts` has no filter and an empty host
 * list, so nothing here ever matches for it.
 */
sealed class WebLink {
    /** `/esim`, `/esim/{ISO2 or region id}`: the eSIM store, on that destination. */
    data class Esim(val dest: String?) : WebLink()
    /** `/number`, `/number/{id}`: the number plans of a destination. */
    data class Number(val dest: String?) : WebLink()
    /** `/me`, `/login`, `/account`: the account surface (direct) or the paywall (play). */
    data object Account : WebLink()
    /** `/buy`: the paywall. */
    data object Buy : WebLink()
    /** `/c/claim?code=`: the account-code restore, same as `rostam://c/claim?code=`. */
    data class Claim(val code: String) : WebLink()
    /** `/app/open?t=`: the website hands this device its signed-in account. */
    data class Open(val token: String) : WebLink()
    /** Any other path on our host. */
    data object Home : WebLink()
}

private val DEST_ID = Regex("^[A-Za-z0-9-]{2,64}$")
private val CODE = Regex("^[A-Za-z0-9-]{4,64}$")
private val TOKEN = Regex("^[A-Za-z0-9._~-]{8,512}$")

/**
 * The route for an https link on one of [hosts], or null when the link is not
 * ours. Pure over the URI's parts so it can be unit-tested without Android.
 * Malformed parameters (an id with a slash, a missing code) fall back to the
 * page rather than to anything that acts on them.
 */
fun webLinkFor(
    scheme: String?,
    host: String?,
    segments: List<String>,
    query: (String) -> String?,
    hosts: List<String>,
): WebLink? {
    if (scheme?.lowercase() != "https") return null
    val h = host?.lowercase() ?: return null
    if (hosts.none { it.equals(h, ignoreCase = true) }) return null
    val words = segments.filter { it.isNotBlank() }
    val id = words.getOrNull(1)?.takeIf { words.size == 2 && DEST_ID.matches(it) }?.lowercase()
    return when (words.firstOrNull()) {
        "esim" -> WebLink.Esim(id)
        "number" -> WebLink.Number(id)
        "me", "login", "account" -> if (words.size == 1) WebLink.Account else WebLink.Home
        "buy" -> if (words.size == 1) WebLink.Buy else WebLink.Home
        "c" -> query("code")?.trim()?.takeIf { words.getOrNull(1) == "claim" && CODE.matches(it) }
            ?.let { WebLink.Claim(it) } ?: WebLink.Home
        "app" -> query("t")?.trim()?.takeIf { words.getOrNull(1) == "open" && TOKEN.matches(it) }
            ?.let { WebLink.Open(it) } ?: WebLink.Home
        else -> WebLink.Home
    }
}

/** The brand's App Link hosts, from the manifest. Empty for a brand without any. */
val webLinkHosts: List<String> =
    BuildConfig.DEEP_LINK_HOSTS.split(',').map { it.trim() }.filter { it.isNotEmpty() }

/**
 * Hand-off from MainActivity to the composed UI. A link can arrive before
 * setContent has produced a VpnViewModel (cold start from the link), so it is
 * parked here and MainScreen consumes it once it runs, instead of being dropped
 * on a null `viewModelRef`.
 */
object WebLinkNav {
    private val _pending = MutableStateFlow<WebLink?>(null)
    val pending: StateFlow<WebLink?> = _pending.asStateFlow()
    fun offer(link: WebLink) { _pending.value = link }
    fun consumed() { _pending.value = null }
}

/**
 * The web-account email this device last signed in with, for display only. The
 * cashier is the truth (`/me/status?cid=`); this just keeps the screen from
 * opening blank while that answers, or when it cannot.
 */
object WebAccountPrefs {
    private const val KEY = "web_account_email"
    private fun prefs(ctx: android.content.Context) =
        ctx.getSharedPreferences("rostam_prefs", android.content.Context.MODE_PRIVATE)
    fun email(ctx: android.content.Context): String? = prefs(ctx).getString(KEY, null)?.ifEmpty { null }
    fun setEmail(ctx: android.content.Context, email: String?) {
        prefs(ctx).edit().apply { if (email.isNullOrEmpty()) remove(KEY) else putString(KEY, email) }.apply()
    }
}
